{
  "name": "kesari-threads",
  "private": true,
  "version": "1.0.0",
  "type": "module",
  "scripts": {
    "dev": "vite",
    "build": "tsc --noEmit && vite build",
    "preview": "vite preview"
  },
  "dependencies": {
    "react": "^19.0.0",
    "react-dom": "^19.0.0"
  },
  "devDependencies": {
    "@types/react": "^19.0.0",
    "@types/react-dom": "^19.0.0",
    "@vitejs/plugin-react": "^4.3.4",
    "typescript": "^5.6.3",
    "vite": "^6.0.0"
  }
}

import { useState } from "react";
import { Role } from "./types";
import { useStore } from "./store";
import Landing from "./components/Landing";
import Login from "./components/Login";
import Workspace from "./components/Workspace";

type View = "landing" | "login" | "workspace";

export default function App() {
  const store = useStore();
  const [view, setView] = useState<View>("landing");
  const [role, setRole] = useState<Role>("manager");

  if (view === "login") {
    return (
      <Login
        onBack={() => setView("landing")}
        onLogin={(r: Role) => {
          setRole(r);
          setView("workspace");
        }}
      />
    );
  }
  if (view === "workspace") {
    return <Workspace store={store} role={role} setRole={setRole} onExit={() => setView("landing")} />;
  }
  return <Landing onExplore={() => setView("login")} />;
}

import { useState } from "react";
import { Store } from "../store";
import { Customer } from "../types";

const empty = { name: "", phone: "+91 ", email: "", city: "" };

export default function Customers({ store }: { store: Store }) {
  const { customers, orders } = store.state;
  const [q, setQ] = useState("");
  const [editing, setEditing] = useState<Customer | null>(null);
  const [adding, setAdding] = useState(false);
  const [form, setForm] = useState(empty);
  const [error, setError] = useState("");

  const term = q.trim().toLowerCase();
  const list = customers.filter(
    (c) => !term || [c.name, c.phone, c.email, c.city].some((x) => x.toLowerCase().includes(term))
  );

  function open(c?: Customer) {
    setError("");
    if (c) {
      setEditing(c);
      setAdding(false);
      setForm({ name: c.name, phone: c.phone, email: c.email, city: c.city });
    } else {
      setEditing(null);
      setAdding(true);
      setForm(empty);
    }
  }
  function close() {
    setEditing(null);
    setAdding(false);
    setError("");
  }
  function save(e: React.FormEvent) {
    e.preventDefault();
    const digits = form.phone.replace(/\D/g, "");
    if (!form.name.trim()) return setError("Please enter a name.");
    if (!/^(91)?[6-9]\d{9}$/.test(digits)) return setError("Enter a valid Indian mobile number, e.g. +91 98450 12345.");
    if (form.email && !/^\S+@\S+\.\S+$/.test(form.email)) return setError("Enter a valid email address.");
    const d = digits.slice(-10);
    const phone = `+91 ${d.slice(0, 5)} ${d.slice(5)}`;
    const data = { name: form.name.trim(), phone, email: form.email.trim(), city: form.city.trim() };
    if (editing) store.updateCustomer({ ...editing, ...data });
    else store.addCustomer(data);
    close();
  }
  const set = (k: keyof typeof empty) => (e: React.ChangeEvent<HTMLInputElement>) =>
    setForm({ ...form, [k]: e.target.value });

  return (
    <section>
      <div className="page-head">
        <div>
          <h1>Customers</h1>
          <p>{customers.length} clients on file</p>
        </div>
        <button className="btn btn-primary" onClick={() => open()}>Add customer</button>
      </div>

      {(adding || editing) && (
        <form className="card form-card" onSubmit={save}>
          <h2>{editing ? "Edit customer" : "New customer"}</h2>
          <div className="form-grid">
            <label>Name<input value={form.name} onChange={set("name")} /></label>
            <label>Phone<input value={form.phone} onChange={set("phone")} inputMode="tel" /></label>
            <label>Email<input value={form.email} onChange={set("email")} type="email" /></label>
            <label>City<input value={form.city} onChange={set("city")} /></label>
          </div>
          {error && <p role="alert" className="error">{error}</p>}
          <div className="row-actions">
            <button className="btn btn-primary" type="submit">Save</button>
            <button className="btn" type="button" onClick={close}>Cancel</button>
          </div>
        </form>
      )}

      <input
        className="search"
        placeholder="Search by name, phone, email or city"
        aria-label="Search customers"
        value={q}
        onChange={(e) => setQ(e.target.value)}
      />

      {list.length === 0 ? (
        <div className="empty">
          <h3>No customers found</h3>
          <p>Try a different search or add a new customer.</p>
        </div>
      ) : (
        <div className="card table-wrap">
          <table>
            <thead>
              <tr><th>Name</th><th>Phone</th><th>Email</th><th>City</th><th>Orders</th><th></th></tr>
            </thead>
            <tbody>
              {list.map((c) => (
                <tr key={c.id}>
                  <td>{c.name}</td>
                  <td>{c.phone}</td>
                  <td>{c.email}</td>
                  <td>{c.city}</td>
                  <td>{orders.filter((o) => o.customerId === c.id).length}</td>
                  <td><button className="btn btn-small" onClick={() => open(c)}>Edit</button></td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </section>
  );
}

import { Store } from "../store";
import { CATEGORIES, LOW_STOCK } from "../types";

const inr = (n: number) => "₹" + n.toLocaleString("en-IN");

export default function Dashboard({ store }: { store: Store }) {
  const { products, orders, returns } = store.state;
  const live = orders.filter((o) => o.status !== "Cancelled");
  const total = (o: (typeof orders)[number]) => o.lines.reduce((a, l) => a + l.price * l.qty, 0);
  const sales = live.reduce((a, o) => a + total(o), 0);
  const liveIds = new Set(live.map((o) => o.id));
  const refunds = returns.filter((r) => liveIds.has(r.orderId)).reduce((a, r) => a + r.refund, 0);
  const units = live.reduce((a, o) => a + o.lines.reduce((b, l) => b + l.qty, 0), 0);
  const low = products.reduce((a, p) => a + p.variants.filter((v) => v.stock <= LOW_STOCK).length, 0);

  const byDate = new Map<string, number>();
  live.forEach((o) => byDate.set(o.date, (byDate.get(o.date) ?? 0) + total(o)));
  const series = [...byDate.entries()].sort((a, b) => a[0].localeCompare(b[0]));
  const maxS = Math.max(1, ...series.map((s) => s[1]));
  const W = 600, H = 200, P = 24;
  const pts = series.map((s, i) => {
    const x = series.length === 1 ? W / 2 : P + (i * (W - P * 2)) / (series.length - 1);
    const y = H - P - (s[1] / maxS) * (H - P * 2);
    return [x, y] as const;
  });
  const path = pts.map((p, i) => `${i ? "L" : "M"}${p[0]},${p[1]}`).join(" ");

  const cat = CATEGORIES.map((c) => ({
    c,
    v: live.reduce((a, o) => a + o.lines.filter((l) => l.category === c).reduce((b, l) => b + l.price * l.qty, 0), 0)
  }));
  const maxC = Math.max(1, ...cat.map((x) => x.v));

  return (
    <div>
      <h1>Dashboard</h1>
      <div className="metrics">
        <div className="card metric"><span>Sales total</span><strong>{inr(sales)}</strong></div>
        <div className="card metric"><span>Orders</span><strong>{live.length}</strong></div>
        <div className="card metric"><span>Units sold</span><strong>{units}</strong></div>
        <div className="card metric"><span>Low-stock variants</span><strong>{low}</strong></div>
        <div className="card metric"><span>Net sales after returns</span><strong>{inr(sales - refunds)}</strong></div>
        <div className="card metric"><span>Returns and exchanges</span><strong>{returns.length}</strong></div>
      </div>
      <div className="charts">
        <section className="card">
          <h2>Sales over time</h2>
          {series.length === 0 ? (
            <p className="empty">No sales yet. Create an order to see the trend.</p>
          ) : (
            <svg viewBox={`0 0 ${W} ${H}`} role="img" aria-label="Sales over time" style={{ width: "100%" }}>
              <path d={path} fill="none" stroke="#f59e0b" strokeWidth="3" />
              {pts.map((p, i) => (
                <circle key={i} cx={p[0]} cy={p[1]} r="4" fill="#1f1a4d"><title>{series[i][0]}: {inr(series[i][1])}</title></circle>
              ))}
              <text x={P} y={H - 4} fontSize="11" fill="#666">{series[0][0]}</text>
              <text x={W - P} y={H - 4} fontSize="11" fill="#666" textAnchor="end">{series[series.length - 1][0]}</text>
            </svg>
          )}
        </section>
        <section className="card">
          <h2>Sales by category</h2>
          {sales === 0 ? (
            <p className="empty">No category sales yet.</p>
          ) : (
            cat.map((x) => (
              <div key={x.c} style={{ margin: "10px 0" }}>
                <div style={{ display: "flex", justifyContent: "space-between", fontSize: 14 }}><span>{x.c}</span><span>{inr(x.v)}</span></div>
                <div style={{ background: "#eee6d6", borderRadius: 6, height: 10 }}>
                  <div style={{ width: `${(x.v / maxC) * 100}%`, background: "#1f1a4d", height: 10, borderRadius: 6 }} />
                </div>
              </div>
            ))
          )}
        </section>
      </div>
    </div>
  );
}

import { useState } from "react";
import { Store } from "../store";
import { CATEGORIES, Category, LOW_STOCK, Product, Role, Variant } from "../types";

const inr = (n: number) => "₹" + n.toLocaleString("en-IN");

interface Draft {
  id?: string;
  name: string;
  category: Category;
  price: string;
  variants: Variant[];
}

const blank = (): Draft => ({
  name: "",
  category: "Kurtas",
  price: "",
  variants: [{ id: "n" + Math.random().toString(36).slice(2, 8), size: "M", colour: "", stock: 5 }]
});

export default function Inventory({ store, role }: { store: Store; role: Role }) {
  const [q, setQ] = useState("");
  const [cat, setCat] = useState<string>("All");
  const [draft, setDraft] = useState<Draft | null>(null);
  const [err, setErr] = useState("");
  const mgr = role === "manager";

  const list = store.state.products.filter(
    (p) => (cat === "All" || p.category === cat) && p.name.toLowerCase().includes(q.trim().toLowerCase())
  );

  const save = () => {
    if (!draft) return;
    const price = Number(draft.price);
    if (!draft.name.trim()) return setErr("Enter a product name.");
    if (!(price > 0)) return setErr("Enter a price above zero.");
    if (draft.variants.length === 0 || draft.variants.some((v) => !v.colour.trim() || !v.size.trim()))
      return setErr("Each variant needs a size and colour.");
    const data = {
      name: draft.name.trim(),
      category: draft.category,
      price,
      variants: draft.variants.map((v) => ({ ...v, stock: Math.max(0, Math.floor(Number(v.stock) || 0)) }))
    };
    if (draft.id) store.updateProduct({ id: draft.id, ...data } as Product);
    else store.addProduct(data);
    setDraft(null);
    setErr("");
  };

  const setV = (i: number, patch: Partial<Variant>) =>
    setDraft((d) => d && { ...d, variants: d.variants.map((v, j) => (j === i ? { ...v, ...patch } : v)) });

  return (
    <div>
      <div className="head-row">
        <h1>Inventory</h1>
        {mgr && <button className="btn primary" onClick={() => { setDraft(blank()); setErr(""); }}>Add product</button>}
      </div>
      {!mgr && <p className="note">Staff view is read-only. Switch to Manager to edit inventory.</p>}
      <div className="toolbar">
        <input aria-label="Search products" placeholder="Search products" value={q} onChange={(e) => setQ(e.target.value)} />
        <select aria-label="Filter by category" value={cat} onChange={(e) => setCat(e.target.value)}>
          <option>All</option>
          {CATEGORIES.map((c) => <option key={c}>{c}</option>)}
        </select>
      </div>

      {draft && mgr && (
        <section className="card" style={{ margin: "16px 0" }}>
          <h2>{draft.id ? "Edit product" : "New product"}</h2>
          <div className="form-grid">
            <label>Name<input value={draft.name} onChange={(e) => setDraft({ ...draft, name: e.target.value })} /></label>
            <label>Category
              <select value={draft.category} onChange={(e) => setDraft({ ...draft, category: e.target.value as Category })}>
                {CATEGORIES.map((c) => <option key={c}>{c}</option>)}
              </select>
            </label>
            <label>Price (INR)<input type="number" min="1" value={draft.price} onChange={(e) => setDraft({ ...draft, price: e.target.value })} /></label>
          </div>
          <h3>Variants</h3>
          {draft.variants.map((v, i) => (
            <div className="form-grid" key={v.id} style={{ alignItems: "end" }}>
              <label>Size<input value={v.size} onChange={(e) => setV(i, { size: e.target.value })} /></label>
              <label>Colour<input value={v.colour} onChange={(e) => setV(i, { colour: e.target.value })} /></label>
              <label>Stock<input type="number" min="0" value={v.stock} onChange={(e) => setV(i, { stock: Number(e.target.value) })} /></label>
              <button className="btn" onClick={() => setDraft({ ...draft, variants: draft.variants.filter((_, j) => j !== i) })}>Remove</button>
            </div>
          ))}
          <button className="btn" onClick={() => setDraft({ ...draft, variants: [...draft.variants, { id: "n" + Math.random().toString(36).slice(2, 8), size: "M", colour: "", stock: 5 }] })}>Add variant</button>
          {err && <p role="alert" className="error">{err}</p>}
          <div style={{ display: "flex", gap: 8, marginTop: 12 }}>
            <button className="btn primary" onClick={save}>Save product</button>
            <button className="btn" onClick={() => setDraft(null)}>Cancel</button>
          </div>
        </section>
      )}

      {list.length === 0 ? (
        <p className="empty">No products match your search. Try another name or category.</p>
      ) : (
        <div className="product-list">
          {list.map((p) => {
            const lowCount = p.variants.filter((v) => v.stock <= LOW_STOCK).length;
            return (
              <article className="card" key={p.id} style={{ marginTop: 12 }}>
                <div className="head-row">
                  <div>
                    <h3 style={{ margin: 0 }}>{p.name}</h3>
                    <small>{p.category} · {inr(p.price)}</small>
                  </div>
                  <div style={{ display: "flex", gap: 8, alignItems: "center", flexWrap: "wrap" }}>
                    {lowCount > 0 && <span className="badge warn">{lowCount} low stock</span>}
                    {mgr && (
                      <>
                        <button className="btn" onClick={() => { setDraft({ id: p.id, name: p.name, category: p.category, price: String(p.price), variants: p.variants.map((v) => ({ ...v })) }); setErr(""); window.scrollTo({ top: 0, behavior: "smooth" }); }}>Edit</button>
                        <button className="btn" onClick={() => { if (window.confirm(`Delete ${p.name}?`)) store.deleteProduct(p.id); }}>Delete</button>
                      </>
                    )}
                  </div>
                </div>
                <div style={{ display: "grid", gap: 6, marginTop: 10 }}>
                  {p.variants.map((v) => (
                    <div key={v.id} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
                      <span>{v.colour} / {v.size}</span>
                      <span style={{ display: "flex", gap: 8, alignItems: "center" }}>
                        {v.stock === 0 ? <span className="badge warn">Out of stock</span> : v.stock <= LOW_STOCK && <span className="badge warn">Low</span>}
                        {mgr && <button className="btn" aria-label={`Decrease stock of ${p.name} ${v.colour} ${v.size}`} onClick={() => store.adjustStock(p.id, v.id, -1)}>−</button>}
                        <strong>{v.stock}</strong>
                        {mgr && <button className="btn" aria-label={`Increase stock of ${p.name} ${v.colour} ${v.size}`} onClick={() => store.adjustStock(p.id, v.id, 1)}>+</button>}
                      </span>
                    </div>
                  ))}
                </div>
              </article>
            );
          })}
        </div>
      )}
    </div>
  );
}

import { useState } from "react";
import { Role } from "../types";

interface Props {
  onBack: () => void;
  onLogin: (r: Role) => void;
}

const ACCOUNTS: { role: Role; title: string; email: string; password: string; blurb: string; can: string[] }[] = [
  {
    role: "manager",
    title: "Manager",
    email: "manager@example.com",
    password: "manager-demo",
    blurb: "Full access to the boutique workspace.",
    can: ["Dashboard and reports", "Add, edit and delete products", "Adjust variant stock", "Customers and orders"]
  },
  {
    role: "staff",
    title: "Staff",
    email: "staff@example.com",
    password: "staff-demo",
    blurb: "Shop-floor access for day-to-day selling.",
    can: ["Dashboard overview", "View products (read-only)", "Customers", "Create and update orders"]
  }
];

export default function Login({ onBack, onLogin }: Props) {
  const [selected, setSelected] = useState<Role>("manager");
  const acc = ACCOUNTS.find((a) => a.role === selected)!;
  const [email, setEmail] = useState(acc.email);
  const [password, setPassword] = useState(acc.password);
  const [error, setError] = useState("");

  function pick(r: Role) {
    const a = ACCOUNTS.find((x) => x.role === r)!;
    setSelected(r);
    setEmail(a.email);
    setPassword(a.password);
    setError("");
  }

  function submit(e: React.FormEvent) {
    e.preventDefault();
    const match = ACCOUNTS.find((a) => a.email === email.trim().toLowerCase() && a.password === password);
    if (!match) {
      setError("These details don't match a demo account. Use one of the credentials shown above.");
      return;
    }
    onLogin(match.role);
  }

  return (
    <main className="login-page" style={{ minHeight: "100vh", padding: "24px", background: "#fbf5e9" }}>
      <div style={{ maxWidth: 880, margin: "0 auto" }}>
        <button type="button" className="btn" onClick={onBack}>← Back to home</button>
        <h1 style={{ fontFamily: "Fraunces, serif", color: "#1f1a4d", marginTop: 24 }}>Enter the demo workspace</h1>
        <p>Choose an account. Credentials are filled in for you.</p>
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(260px,1fr))", gap: 16, margin: "20px 0" }}>
          {ACCOUNTS.map((a) => (
            <button
              key={a.role}
              type="button"
              onClick={() => pick(a.role)}
              aria-pressed={selected === a.role}
              style={{
                textAlign: "left",
                padding: 20,
                borderRadius: 16,
                cursor: "pointer",
                background: "#fff",
                font: "inherit",
                border: selected === a.role ? "2px solid #f59e0b" : "2px solid #e5dcc8"
              }}
            >
              <strong style={{ fontFamily: "Fraunces, serif", fontSize: 22, color: "#1f1a4d" }}>{a.title}</strong>
              <p style={{ margin: "6px 0" }}>{a.blurb}</p>
              <p style={{ margin: 0, fontSize: 14 }}>Email: <code>{a.email}</code></p>
              <p style={{ margin: "0 0 8px", fontSize: 14 }}>Password: <code>{a.password}</code></p>
              <ul style={{ margin: 0, paddingLeft: 18, fontSize: 14 }}>
                {a.can.map((c) => <li key={c}>{c}</li>)}
              </ul>
            </button>
          ))}
        </div>
        <form onSubmit={submit} style={{ background: "#fff", padding: 20, borderRadius: 16, display: "grid", gap: 12, maxWidth: 420 }}>
          <label>Email<input type="email" value={email} onChange={(e) => setEmail(e.target.value)} style={{ display: "block", width: "100%", padding: 8 }} /></label>
          <label>Password<input type="text" value={password} onChange={(e) => setPassword(e.target.value)} style={{ display: "block", width: "100%", padding: 8 }} /></label>
          {error && <p role="alert" style={{ color: "#b91c1c", margin: 0 }}>{error}</p>}
          <button type="submit" className="btn primary">Sign in as {acc.title}</button>
        </form>
        <p style={{ marginTop: 20, padding: 14, background: "#fff3d6", borderRadius: 12, maxWidth: 560 }}>
          <strong>Frontend demonstration only.</strong> This is not secure authentication. No accounts, passwords or data are sent anywhere; everything stays in your browser.
        </p>
      </div>
    </main>
  );
}

import { useState } from "react";
import { Store, returnedQty } from "../store";
import { OrderStatus, STATUSES, Order, ReturnReason, ReturnType } from "../types";

const REASONS: ReturnReason[] = ["Size issue", "Damaged", "Changed mind", "Other"];

const inr = (n: number) => "₹" + n.toLocaleString("en-IN");

interface Item {
  productId: string;
  variantId: string;
  qty: number;
}

export default function Orders({ store }: { store: Store }) {
  const { products, customers, orders } = store.state;
  const [open, setOpen] = useState(false);
  const [customerId, setCustomerId] = useState("");
  const [items, setItems] = useState<Item[]>([]);
  const [pid, setPid] = useState("");
  const [vid, setVid] = useState("");
  const [qty, setQty] = useState(1);
  const [msg, setMsg] = useState<{ ok: boolean; text: string } | null>(null);
  const [filter, setFilter] = useState<"All" | OrderStatus>("All");
  const [retFor, setRetFor] = useState<string | null>(null);
  const [rVid, setRVid] = useState("");
  const [rQty, setRQty] = useState(1);
  const [rType, setRType] = useState<ReturnType>("Return");
  const [rReason, setRReason] = useState<ReturnReason>("Size issue");
  const [rNew, setRNew] = useState("");
  const allReturns = store.state.returns;

  const leftFor = (o: Order, variantId: string) =>
    o.lines.filter((l) => l.variantId === variantId).reduce((a, l) => a + l.qty, 0) - returnedQty(allReturns, o.id, variantId);

  function openReturn(id: string) {
    setRetFor(retFor === id ? null : id);
    setRVid("");
    setRQty(1);
    setRType("Return");
    setRReason("Size issue");
    setRNew("");
    setMsg(null);
  }

  function submitReturn(orderId: string) {
    const r = store.recordReturn({ orderId, variantId: rVid, qty: rQty, type: rType, reason: rReason, newVariantId: rType === "Exchange" ? rNew : undefined });
    if (!r.ok) return setMsg({ ok: false, text: r.error ?? "Could not record this." });
    setMsg({ ok: true, text: rType === "Return" ? "Return recorded, stock restored and refund noted." : "Exchange recorded and stock adjusted." });
    setRetFor(null);
  }

  const product = products.find((p) => p.id === pid);
  const variant = product?.variants.find((v) => v.id === vid);
  const reserved = (id: string) => items.filter((i) => i.variantId === id).reduce((a, i) => a + i.qty, 0);
  const available = variant ? variant.stock - reserved(variant.id) : 0;

  function addItem() {
    if (!product || !variant) return setMsg({ ok: false, text: "Choose a product and variant." });
    if (qty < 1) return setMsg({ ok: false, text: "Quantity must be at least 1." });
    if (qty > available) return setMsg({ ok: false, text: `Only ${available} available for that variant.` });
    setItems([...items, { productId: product.id, variantId: variant.id, qty }]);
    setQty(1);
    setVid("");
    setMsg(null);
  }

  const lookup = (it: Item) => {
    const p = products.find((x) => x.id === it.productId);
    const v = p?.variants.find((x) => x.id === it.variantId);
    return { p, v };
  };
  const total = items.reduce((a, it) => a + (lookup(it).p?.price ?? 0) * it.qty, 0);

  function submit() {
    const r = store.createOrder(customerId, items);
    if (!r.ok) return setMsg({ ok: false, text: r.error ?? "Could not create order." });
    setMsg({ ok: true, text: "Order created and stock updated." });
    setItems([]);
    setCustomerId("");
    setPid("");
    setVid("");
    setOpen(false);
  }

  function change(id: string, s: OrderStatus) {
    const r = store.setOrderStatus(id, s);
    setMsg(r.ok ? null : { ok: false, text: r.error ?? "Status change failed." });
  }

  const shown = orders
    .filter((o) => filter === "All" || o.status === filter)
    .slice()
    .sort((a, b) => b.date.localeCompare(a.date));

  return (
    <section>
      <div className="page-head">
        <div>
          <h1>Orders</h1>
          <p>{orders.length} orders recorded</p>
        </div>
        <button className="btn btn-primary" onClick={() => setOpen(!open)}>{open ? "Close" : "New order"}</button>
      </div>

      {msg && <p role="status" className={msg.ok ? "notice" : "error"}>{msg.text}</p>}

      {open && (
        <div className="card form-card">
          <h2>Create order</h2>
          <div className="form-grid">
            <label>Customer
              <select value={customerId} onChange={(e) => setCustomerId(e.target.value)}>
                <option value="">Select customer</option>
                {customers.map((c) => <option key={c.id} value={c.id}>{c.name} · {c.city}</option>)}
              </select>
            </label>
            <label>Product
              <select value={pid} onChange={(e) => { setPid(e.target.value); setVid(""); }}>
                <option value="">Select product</option>
                {products.map((p) => <option key={p.id} value={p.id}>{p.name} · {inr(p.price)}</option>)}
              </select>
            </label>
            <label>Variant
              <select value={vid} onChange={(e) => setVid(e.target.value)} disabled={!product}>
                <option value="">Select variant</option>
                {product?.variants.map((v) => (
                  <option key={v.id} value={v.id} disabled={v.stock - reserved(v.id) <= 0}>
                    {v.colour} / {v.size} ({v.stock - reserved(v.id)} left)
                  </option>
                ))}
              </select>
            </label>
            <label>Quantity
              <input type="number" min={1} max={Math.max(1, available)} value={qty} onChange={(e) => setQty(Math.floor(Number(e.target.value)) || 0)} />
            </label>
          </div>
          <div className="row-actions">
            <button className="btn" type="button" onClick={addItem}>Add item</button>
            {variant && <span className="hint">{available} available</span>}
          </div>

          {items.length === 0 ? (
            <div className="empty"><p>No items yet. Pick a product variant and add it.</p></div>
          ) : (
            <ul className="line-list">
              {items.map((it, i) => {
                const { p, v } = lookup(it);
                return (
                  <li key={i}>
                    <span>{p?.name} — {v?.colour} / {v?.size} × {it.qty}</span>
                    <span>{inr((p?.price ?? 0) * it.qty)}</span>
                    <button className="btn btn-small" onClick={() => setItems(items.filter((_, j) => j !== i))}>Remove</button>
                  </li>
                );
              })}
            </ul>
          )}
          <div className="row-actions">
            <strong>Total: {inr(total)}</strong>
            <button className="btn btn-primary" onClick={submit}>Place order</button>
          </div>
        </div>
      )}

      <div className="chips" role="group" aria-label="Filter by status">
        {(["All", ...STATUSES] as const).map((s) => (
          <button key={s} className={"chip" + (filter === s ? " active" : "")} onClick={() => setFilter(s)}>{s}</button>
        ))}
      </div>

      {shown.length === 0 ? (
        <div className="empty">
          <h3>No orders here</h3>
          <p>Create an order or choose a different status filter.</p>
        </div>
      ) : (
        <div className="order-list">
          {shown.map((o) => {
            const c = customers.find((x) => x.id === o.customerId);
            const sum = o.lines.reduce((a, l) => a + l.price * l.qty, 0);
            const recs = allReturns.filter((r) => r.orderId === o.id);
            const retLine = o.lines.find((l) => l.variantId === rVid);
            const retProduct = products.find((p) => p.id === retLine?.productId);
            const choices = o.lines.filter((l, i, arr) => arr.findIndex((x) => x.variantId === l.variantId) === i && leftFor(o, l.variantId) > 0);
            return (
              <article key={o.id} className="card order-card">
                <header>
                  <div>
                    <strong>{c?.name ?? "Unknown customer"}</strong>
                    <span className="hint"> · {o.date}</span>
                  </div>
                  <span className={"badge status-" + o.status.toLowerCase()}>{o.status}</span>
                </header>
                <ul className="line-list">
                  {o.lines.map((l, i) => (
                    <li key={i}>
                      <span>{l.name} — {l.label} × {l.qty}</span>
                      <span>{inr(l.price * l.qty)}</span>
                    </li>
                  ))}
                </ul>
                {recs.length > 0 && (
                  <div>
                    <h3>Returns and exchanges</h3>
                    <ul className="line-list">
                      {recs.map((r) => (
                        <li key={r.id}>
                          <span>{r.type}: {r.name} — {r.label}{r.type === "Exchange" && r.newLabel ? ` → ${r.newLabel}` : ""} × {r.qty} · {r.reason}</span>
                          <span>{r.refund > 0 ? "Refund " + inr(r.refund) : "No refund"}</span>
                        </li>
                      ))}
                    </ul>
                  </div>
                )}
                {o.status === "Delivered" && (
                  <div className="row-actions">
                    <button className="btn btn-small" type="button" onClick={() => openReturn(o.id)}>{retFor === o.id ? "Close" : "Record return or exchange"}</button>
                  </div>
                )}
                {retFor === o.id && (
                  <div className="card form-card">
                    {choices.length === 0 ? (
                      <p className="hint">Every item on this order has already been returned or exchanged.</p>
                    ) : (
                      <>
                        <div className="form-grid">
                          <label>Item
                            <select value={rVid} onChange={(e) => { setRVid(e.target.value); setRQty(1); setRNew(""); }}>
                              <option value="">Select item</option>
                              {choices.map((l) => <option key={l.variantId} value={l.variantId}>{l.name} — {l.label} ({leftFor(o, l.variantId)} left)</option>)}
                            </select>
                          </label>
                          <label>Quantity
                            <input type="number" min={1} max={rVid ? leftFor(o, rVid) : 1} value={rQty} onChange={(e) => setRQty(Math.floor(Number(e.target.value)) || 0)} />
                          </label>
                          <label>Type
                            <select value={rType} onChange={(e) => setRType(e.target.value as ReturnType)}>
                              <option>Return</option>
                              <option>Exchange</option>
                            </select>
                          </label>
                          <label>Reason
                            <select value={rReason} onChange={(e) => setRReason(e.target.value as ReturnReason)}>
                              {REASONS.map((x) => <option key={x}>{x}</option>)}
                            </select>
                          </label>
                          {rType === "Exchange" && (
                            <label>Exchange for
                              <select value={rNew} onChange={(e) => setRNew(e.target.value)} disabled={!retLine}>
                                <option value="">Select size or colour</option>
                                {retProduct?.variants.filter((v) => v.id !== rVid).map((v) => (
                                  <option key={v.id} value={v.id} disabled={v.stock < rQty}>{v.colour} / {v.size} ({v.stock} in stock)</option>
                                ))}
                              </select>
                            </label>
                          )}
                        </div>
                        {retLine && rType === "Return" && <p className="hint">Refund: {inr(retLine.price * Math.max(0, rQty))}</p>}
                        <div className="row-actions">
                          <button className="btn btn-primary" type="button" onClick={() => submitReturn(o.id)}>Save {rType.toLowerCase()}</button>
                        </div>
                      </>
                    )}
                  </div>
                )}
                <footer className="row-actions">
                  <strong>{inr(sum)}</strong>
                  <label className="inline">Status
                    <select value={o.status} onChange={(e) => change(o.id, e.target.value as OrderStatus)}>
                      {STATUSES.map((s) => <option key={s}>{s}</option>)}
                    </select>
                  </label>
                </footer>
              </article>
            );
          })}
        </div>
      )}
    </section>
  );
}

import { Store } from "../store";
import { CATEGORIES } from "../types";

const inr = (n: number) => "₹" + n.toLocaleString("en-IN");

export default function Reports({ store }: { store: Store }) {
  const lines = store.state.orders.filter((o) => o.status !== "Cancelled").flatMap((o) => o.lines);
  const byCat = CATEGORIES.map((c) => {
    const ls = lines.filter((l) => l.category === c);
    return { name: c, revenue: ls.reduce((a, l) => a + l.price * l.qty, 0), units: ls.reduce((a, l) => a + l.qty, 0) };
  });
  const totalRev = byCat.reduce((a, c) => a + c.revenue, 0);
  const maxCat = Math.max(1, ...byCat.map((c) => c.revenue));
  const map = new Map<string, { name: string; category: string; units: number; revenue: number }>();
  for (const l of lines) {
    const e = map.get(l.productId) ?? { name: l.name, category: l.category, units: 0, revenue: 0 };
    e.units += l.qty;
    e.revenue += l.price * l.qty;
    map.set(l.productId, e);
  }
  const top = [...map.values()].sort((a, b) => b.revenue - a.revenue).slice(0, 8);
  const liveOrders = store.state.orders.filter((o) => o.status !== "Cancelled");
  const refundByCat = new Map<string, number>();
  for (const r of store.state.returns) {
    const o = liveOrders.find((x) => x.id === r.orderId);
    if (!o) continue;
    const l = o.lines.find((x) => x.variantId === r.variantId);
    if (!l) continue;
    refundByCat.set(l.category, (refundByCat.get(l.category) ?? 0) + r.refund);
  }
  const net = byCat.map((c) => {
    const refunded = refundByCat.get(c.name) ?? 0;
    return { name: c.name, gross: c.revenue, refunded, net: c.revenue - refunded };
  });
  const netTotal = net.reduce((a, c) => a + c.net, 0);
  const maxNet = Math.max(1, ...net.map((c) => c.net));

  return (
    <div className="reports">
      <div className="page-head">
        <h1>Reports</h1>
        <p className="muted">Derived from all orders that are not cancelled.</p>
      </div>
      <div className="report-grid">
        <section className="card">
          <h2>Sales by category</h2>
          {totalRev === 0 ? (
            <div className="empty">No sales yet. Create an order to see category revenue.</div>
          ) : (
            <ul className="bar-list">
              {byCat.map((c) => (
                <li key={c.name}>
                  <div className="bar-row">
                    <span>{c.name}</span>
                    <strong>{inr(c.revenue)}</strong>
                  </div>
                  <div className="bar-track">
                    <div className="bar-fill" style={{ width: `${(c.revenue / maxCat) * 100}%` }} />
                  </div>
                  <small className="muted">
                    {c.units} units · {totalRev ? Math.round((c.revenue / totalRev) * 100) : 0}% of sales
                  </small>
                </li>
              ))}
            </ul>
          )}
        </section>
        <section className="card net-sales">
          <h2>Net sales by category after returns</h2>
          {totalRev === 0 ? (
            <div className="empty">Net sales will appear once orders are placed.</div>
          ) : (
            <ul className="bar-list">
              {net.map((c) => (
                <li key={c.name}>
                  <div className="bar-row">
                    <span>{c.name}</span>
                    <strong>{inr(c.net)}</strong>
                  </div>
                  <div className="bar-track">
                    <div className="bar-fill" style={{ width: `${(Math.max(0, c.net) / maxNet) * 100}%` }} />
                  </div>
                  <small className="muted">
                    {inr(c.gross)} sales − {inr(c.refunded)} refunds
                  </small>
                </li>
              ))}
              <li className="bar-row">
                <span>Total net sales</span>
                <strong>{inr(netTotal)}</strong>
              </li>
            </ul>
          )}
        </section>
        <section className="card">
          <h2>Top products</h2>
          {top.length === 0 ? (
            <div className="empty">Top sellers will appear once orders are placed.</div>
          ) : (
            <div className="table-wrap">
              <table>
                <thead>
                  <tr>
                    <th>#</th>
                    <th>Product</th>
                    <th>Units</th>
                    <th>Revenue</th>
                  </tr>
                </thead>
                <tbody>
                  {top.map((p, i) => (
                    <tr key={p.name}>
                      <td>{i + 1}</td>
                      <td>
                        {p.name}
                        <br />
                        <small className="muted">{p.category}</small>
                      </td>
                      <td>{p.units}</td>
                      <td>{inr(p.revenue)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </section>
      </div>
    </div>
  );
}

import { useState } from "react";
import { Store } from "../store";
import { RETURN_REASONS, RETURN_TYPES, ReturnReason, ReturnType } from "../types";

const inr = (n: number) => "₹" + n.toLocaleString("en-IN");

export default function Returns({ store }: { store: Store }) {
  const { returns, customers } = store.state;
  const [type, setType] = useState<ReturnType | "All">("All");
  const [reason, setReason] = useState<ReturnReason | "All">("All");

  const rows = returns
    .filter((r) => (type === "All" || r.type === type) && (reason === "All" || r.reason === reason))
    .slice()
    .sort((a, b) => b.date.localeCompare(a.date));
  const refunded = rows.reduce((a, r) => a + r.refund, 0);
  const cname = (id: string) => customers.find((c) => c.id === id)?.name ?? "Unknown customer";

  return (
    <section>
      <div className="page-head">
        <div>
          <h1 style={{ fontSize: "2rem" }}>Returns &amp; exchanges</h1>
          <p className="muted" style={{ margin: 0 }}>
            {rows.length} record{rows.length === 1 ? "" : "s"} shown · {inr(refunded)} refunded
          </p>
        </div>
      </div>
      <div className="toolbar">
        <label className="inline">
          Type
          <select value={type} onChange={(e) => setType(e.target.value as ReturnType | "All")}>
            <option value="All">All types</option>
            {RETURN_TYPES.map((t) => (
              <option key={t} value={t}>{t}</option>
            ))}
          </select>
        </label>
        <label className="inline">
          Reason
          <select value={reason} onChange={(e) => setReason(e.target.value as ReturnReason | "All")}>
            <option value="All">All reasons</option>
            {RETURN_REASONS.map((t) => (
              <option key={t} value={t}>{t}</option>
            ))}
          </select>
        </label>
        {(type !== "All" || reason !== "All") && (
          <button className="btn sm" onClick={() => { setType("All"); setReason("All"); }}>Clear filters</button>
        )}
      </div>
      {rows.length === 0 ? (
        <div className="empty">
          <h3>{returns.length === 0 ? "No returns or exchanges yet" : "Nothing matches these filters"}</h3>
          <p>
            {returns.length === 0
              ? "Record one from a Delivered order on the Orders page."
              : "Try a different type or reason, or clear the filters."}
          </p>
        </div>
      ) : (
        <div className="card table-wrap">
          <table>
            <thead>
              <tr>
                <th>Date</th><th>Type</th><th>Order</th><th>Customer</th><th>Item</th><th>Qty</th><th>Reason</th><th>Refund</th>
              </tr>
            </thead>
            <tbody>
              {rows.map((r) => (
                <tr key={r.id}>
                  <td>{r.date}</td>
                  <td><span className={"badge " + (r.type === "Return" ? "warn" : "")}>{r.type}</span></td>
                  <td>#{r.orderId.slice(-6).toUpperCase()}</td>
                  <td>{cname(r.customerId)}</td>
                  <td>
                    {r.name}
                    <div className="hint">
                      {r.label}{r.type === "Exchange" && r.newLabel ? ` → ${r.newLabel}` : ""}
                    </div>
                  </td>
                  <td>{r.qty}</td>
                  <td>{r.reason}</td>
                  <td>{r.refund > 0 ? inr(r.refund) : "—"}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </section>
  );
}

import { useState } from "react";
import { Role } from "../types";
import { Store } from "../store";
import Dashboard from "./Dashboard";
