interface Props {
  store: Store;
  role: Role;
  setRole: (r: Role) => void;
  onExit: () => void;
}

type Section = "dashboard" | "inventory" | "customers" | "orders" | "returns" | "reports";

const NAV: { id: Section; label: string; managerOnly?: boolean }[] = [
  { id: "dashboard", label: "Dashboard" },
  { id: "inventory", label: "Inventory" },
  { id: "customers", label: "Customers" },
  { id: "orders", label: "Orders" },
  { id: "returns", label: "Returns" },
  { id: "reports", label: "Reports", managerOnly: true }
];

export default function Workspace({ store, role, setRole, onExit }: Props) {
  const [section, setSection] = useState<Section>("dashboard");
  const [open, setOpen] = useState(false);
  const isManager = role === "manager";
  const current: Section = section === "reports" && !isManager ? "dashboard" : section;

  function go(s: Section) {
    setSection(s);
    setOpen(false);
  }

  function doReset() {
    if (window.confirm("Reset all demo data to the original seed? Your changes will be lost.")) store.reset();
  }

  return (
    <div className={"workspace" + (open ? " menu-open" : "")} style={{ display: "flex", minHeight: "100vh" }}>
      <button
        type="button"
        className="menu-toggle"
        aria-label={open ? "Close menu" : "Open menu"}
        aria-expanded={open}
        onClick={() => setOpen(!open)}
      >
        {open ? "✕" : "☰"}
      </button>
      <aside className="sidebar" aria-label="Workspace navigation">
        <div className="brand" style={{ fontFamily: "Fraunces, serif", fontSize: 22 }}>Kesari Threads</div>
        <nav>
          {NAV.filter((n) => !n.managerOnly || isManager).map((n) => (
            <button
              key={n.id}
              type="button"
              className={"nav-item" + (current === n.id ? " active" : "")}
              aria-current={current === n.id ? "page" : undefined}
              onClick={() => go(n.id)}
            >
              {n.label}
            </button>
          ))}
        </nav>
        <div className="side-foot">
          <label>
            Role
            <select value={role} onChange={(e) => setRole(e.target.value as Role)}>
              <option value="manager">Manager</option>
              <option value="staff">Staff</option>
            </select>
          </label>
          <button type="button" className="btn" onClick={doReset}>Reset demo data</button>
          <button type="button" className="btn" onClick={onExit}>Exit demo</button>
          <small>Frontend demo, not secure authentication.</small>
        </div>
      </aside>
      {open && <div className="scrim" onClick={() => setOpen(false)} aria-hidden="true" />}
      <main className="content" style={{ flex: 1, minWidth: 0 }}>
        {current === "dashboard" && <Dashboard store={store} />}
        {current === "inventory" && <Inventory store={store} role={role} />}
        {current === "customers" && <Customers store={store} />}
        {current === "orders" && <Orders store={store} />}
        {current === "returns" && <Returns store={store} />}
        {current === "reports" && isManager && <Reports store={store} />}
      </main>
    </div>
  );
}

import { AppState, Category, Customer, Order, OrderLine, Product, ReturnRecord } from "./types";

const clothSizes = ["S", "M", "L"];
const free = ["Free size"];

function mk(
  n: number,
  name: string,
  category: Category,
  price: number,
  sizes: string[],
  colours: string[],
  stocks: number[]
): Product {
  const variants = [] as Product["variants"];
  let i = 0;
  for (const colour of colours) {
    for (const size of sizes) {
      variants.push({ id: `v${n}-${i}`, size, colour, stock: stocks[i % stocks.length] });
      i++;
    }
  }
  return { id: `p${n}`, name, category, price, variants };
}

