function daysAgo(n: number): string {
  const d = new Date();
  d.setDate(d.getDate() - n);
  return d.toISOString().slice(0, 10);
}

function line(products: Product[], pid: string, vi: number, qty: number): OrderLine {
  const p = products.find((x) => x.id === pid)!;
  const v = p.variants[vi];
  return {
    productId: p.id,
    variantId: v.id,
    name: p.name,
    category: p.category,
    label: `${v.colour} / ${v.size}`,
    price: p.price,
    qty
  };
}

export function buildSeed(): AppState {
  const products: Product[] = JSON.parse(JSON.stringify(seedProducts));
  const specs: [string, string, Order["status"], number, [string, number, number][]][] = [
    ["o1", "c1", "Delivered", 27, [["p6", 0, 1], ["p18", 0, 1]]],
    ["o2", "c2", "Delivered", 24, [["p1", 1, 2]]],
    ["o3", "c3", "Delivered", 21, [["p8", 0, 1], ["p15", 0, 1]]],
    ["o4", "c4", "Delivered", 18, [["p12", 0, 1]]],
    ["o5", "c5", "Delivered", 15, [["p2", 1, 2], ["p19", 0, 1]]],
    ["o6", "c6", "Cancelled", 13, [["p11", 0, 1]]],
    ["o7", "c7", "Delivered", 11, [["p7", 0, 1]]],
    ["o8", "c8", "Packed", 8, [["p13", 1, 1], ["p17", 0, 2]]],
    ["o9", "c9", "Packed", 5, [["p3", 0, 2], ["p22", 0, 1]]],
    ["o10", "c10", "New", 3, [["p10", 0, 1], ["p16", 0, 1]]],
    ["o11", "c11", "New", 1, [["p5", 1, 3], ["p20", 1, 1]]],
    ["o12", "c12", "New", 0, [["p4", 0, 1], ["p21", 0, 1]]]
  ];
  const orders: Order[] = specs.map(([id, customerId, status, ago, ls]) => ({
    id,
    customerId,
    status,
    date: daysAgo(ago),
    lines: ls.map(([pid, vi, q]) => line(products, pid, vi, q))
  }));
  // Seed stock figures are already net of these orders; no deduction needed.
  // Sample returns: stock figures below are adjusted to match.
  const returns: ReturnRecord[] = [];
  const bump = (vid: string, d: number) => {
    for (const p of products) for (const v of p.variants) if (v.id === vid) v.stock += d;
  };
  const find = (oid: string, i: number) => {
    const o = orders.find((x) => x.id === oid)!;
    return { o, l: o.lines[i] };
  };
  const add = (id: string, oid: string, li: number, type: ReturnRecord["type"], reason: ReturnRecord["reason"], ago: number, qty: number, newVi?: number) => {
    const { o, l } = find(oid, li);
    const rec: ReturnRecord = {
      id, type, reason, orderId: o.id, customerId: o.customerId, date: daysAgo(ago),
      productId: l.productId, name: l.name, category: l.category, variantId: l.variantId,
      label: l.label, qty, refund: type === "Return" ? l.price * qty : 0
    };
    bump(l.variantId, qty);
    if (type === "Exchange" && newVi !== undefined) {
      const nv = products.find((p) => p.id === l.productId)!.variants[newVi];
      rec.newVariantId = nv.id;
      rec.newLabel = `${nv.colour} / ${nv.size}`;
      bump(nv.id, -qty);
    }
    returns.push(rec);
  };
  add("r1", "o2", 0, "Exchange", "Size issue", 20, 1, 5);
  add("r2", "o3", 1, "Return", "Changed mind", 17, 1);
  add("r3", "o5", 1, "Return", "Damaged", 10, 1);
  return { products, customers: JSON.parse(JSON.stringify(seedCustomers)), orders, returns };
}

