import { useCallback, useEffect, useState } from "react";
import { AppState, Customer, Order, OrderLine, OrderStatus, Product, ReturnReason, ReturnRecord, ReturnType } from "./types";
import { buildSeed } from "./data";

const KEY = "kesari-threads-state-v1";

function load(): AppState {
  try {
    const raw = localStorage.getItem(KEY);
    if (raw) {
      const p = JSON.parse(raw) as Omit<AppState, "returns"> & { returns?: ReturnRecord[] };
      if (Array.isArray(p.products) && Array.isArray(p.customers) && Array.isArray(p.orders))
        return { ...p, returns: Array.isArray(p.returns) ? p.returns : [] };
    }
  } catch {
    /* ignore */
  }
  return buildSeed();
}

function uid(prefix: string): string {
  return `${prefix}${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;
}

export function returnedQty(returns: ReturnRecord[], orderId: string, variantId: string): number {
  return returns.filter((r) => r.orderId === orderId && r.variantId === variantId).reduce((a, r) => a + r.qty, 0);
}

export interface RecordReturnInput {
  orderId: string;
  variantId: string;
  qty: number;
  type: ReturnType;
  reason: ReturnReason;
  newVariantId?: string;
}

export interface Store {
  recordReturn: (input: RecordReturnInput) => { ok: boolean; error?: string };
  state: AppState;
  addProduct: (p: Omit<Product, "id">) => void;
  updateProduct: (p: Product) => void;
  deleteProduct: (id: string) => void;
  adjustStock: (productId: string, variantId: string, delta: number) => void;
  addCustomer: (c: Omit<Customer, "id">) => void;
  updateCustomer: (c: Customer) => void;
  createOrder: (customerId: string, items: { productId: string; variantId: string; qty: number }[]) => { ok: boolean; error?: string };
  setOrderStatus: (id: string, status: OrderStatus) => { ok: boolean; error?: string };
  reset: () => void;
}

export function useStore(): Store {
  const [state, setState] = useState<AppState>(load);

  useEffect(() => {
    try {
      localStorage.setItem(KEY, JSON.stringify(state));
    } catch {
      /* ignore */
    }
  }, [state]);

  const addProduct = useCallback((p: Omit<Product, "id">) => {
    setState((s) => ({ ...s, products: [{ ...p, id: uid("p") }, ...s.products] }));
  }, []);

  const updateProduct = useCallback((p: Product) => {
    setState((s) => ({ ...s, products: s.products.map((x) => (x.id === p.id ? p : x)) }));
  }, []);

  const deleteProduct = useCallback((id: string) => {
    setState((s) => ({ ...s, products: s.products.filter((x) => x.id !== id) }));
  }, []);

  const adjustStock = useCallback((productId: string, variantId: string, delta: number) => {
    setState((s) => ({
      ...s,
      products: s.products.map((p) =>
        p.id !== productId
          ? p
          : { ...p, variants: p.variants.map((v) => (v.id === variantId ? { ...v, stock: Math.max(0, v.stock + delta) } : v)) }
      )
    }));
  }, []);

  const addCustomer = useCallback((c: Omit<Customer, "id">) => {
    setState((s) => ({ ...s, customers: [{ ...c, id: uid("c") }, ...s.customers] }));
  }, []);

  const updateCustomer = useCallback((c: Customer) => {
    setState((s) => ({ ...s, customers: s.customers.map((x) => (x.id === c.id ? c : x)) }));
  }, []);

  const createOrder = useCallback(
    (customerId: string, items: { productId: string; variantId: string; qty: number }[]) => {
      if (!customerId) return { ok: false, error: "Choose a customer first." };
      if (items.length === 0) return { ok: false, error: "Add at least one item." };
      const need = new Map<string, number>();
      for (const it of items) need.set(it.variantId, (need.get(it.variantId) ?? 0) + it.qty);
      const lines: OrderLine[] = [];
      for (const it of items) {
        const p = state.products.find((x) => x.id === it.productId);
        const v = p?.variants.find((x) => x.id === it.variantId);
        if (!p || !v) return { ok: false, error: "A selected product is no longer available." };
        if (it.qty < 1) return { ok: false, error: "Quantities must be at least 1." };
        if ((need.get(v.id) ?? 0) > v.stock)
          return { ok: false, error: `Only ${v.stock} of ${p.name} (${v.colour} / ${v.size}) in stock.` };
        lines.push({
          productId: p.id,
          variantId: v.id,
          name: p.name,
          category: p.category,
          label: `${v.colour} / ${v.size}`,
          price: p.price,
          qty: it.qty
        });
      }
      const order: Order = {
        id: uid("o"),
        customerId,
        date: new Date().toISOString().slice(0, 10),
        status: "New",
        lines
      };
      setState((s) => ({
        ...s,
        orders: [order, ...s.orders],
        products: s.products.map((p) => ({
          ...p,
          variants: p.variants.map((v) => (need.has(v.id) ? { ...v, stock: v.stock - need.get(v.id)! } : v))
        }))
      }));
      return { ok: true };
    },
    [state.products]
  );

  const setOrderStatus = useCallback(
    (id: string, status: OrderStatus) => {
      const o = state.orders.find((x) => x.id === id);
      if (!o || o.status === status) return { ok: true };
      const cancelling = status === "Cancelled";
      const reviving = o.status === "Cancelled";
      if (reviving) {
        for (const l of o.lines) {
          const v = state.products.find((p) => p.id === l.productId)?.variants.find((x) => x.id === l.variantId);
          if (!v || v.stock < l.qty)
            return { ok: false, error: `Not enough stock of ${l.name} (${l.label}) to reopen this order.` };
        }
      }
      setState((s) => ({
        ...s,
        orders: s.orders.map((x) => (x.id === id ? { ...x, status } : x)),
        products:
          cancelling || reviving
            ? s.products.map((p) => ({
                ...p,
                variants: p.variants.map((v) => {
                  const q = o.lines.filter((l) => l.variantId === v.id).reduce((a, l) => a + l.qty, 0);
                  if (!q) return v;
                  return { ...v, stock: cancelling ? v.stock + q : v.stock - q };
                })
              }))
            : s.products
      }));
      return { ok: true };
    },
    [state.orders, state.products]
  );

  const recordReturn = useCallback(
    (input: RecordReturnInput) => {
      const o = state.orders.find((x) => x.id === input.orderId);
      if (!o) return { ok: false, error: "Order not found." };
      if (o.status !== "Delivered") return { ok: false, error: "Only delivered orders can have returns or exchanges." };
      const l = o.lines.find((x) => x.variantId === input.variantId);
      if (!l) return { ok: false, error: "Choose an item from this order." };
      const ordered = o.lines.filter((x) => x.variantId === l.variantId).reduce((a, x) => a + x.qty, 0);
      const left = ordered - returnedQty(state.returns, o.id, l.variantId);
      if (!Number.isInteger(input.qty) || input.qty < 1) return { ok: false, error: "Quantity must be at least 1." };
      if (input.qty > left) return { ok: false, error: `Only ${left} left to return or exchange for this item.` };
      const product = state.products.find((p) => p.id === l.productId);
      let newLabel: string | undefined;
      if (input.type === "Exchange") {
        const nv = product?.variants.find((v) => v.id === input.newVariantId);
        if (!product || !nv) return { ok: false, error: "Choose a size or colour to exchange to." };
        if (nv.id === l.variantId) return { ok: false, error: "Choose a different size or colour." };
        if (nv.stock < input.qty) return { ok: false, error: `Only ${nv.stock} in stock for ${nv.colour} / ${nv.size}.` };
        newLabel = `${nv.colour} / ${nv.size}`;
      }
      const rec: ReturnRecord = {
        id: uid("r"),
        type: input.type,
        reason: input.reason,
        orderId: o.id,
        customerId: o.customerId,
        date: new Date().toISOString().slice(0, 10),
        productId: l.productId,
        name: l.name,
        category: l.category,
        variantId: l.variantId,
        label: l.label,
        newVariantId: input.type === "Exchange" ? input.newVariantId : undefined,
        newLabel,
        qty: input.qty,
        refund: input.type === "Return" ? l.price * input.qty : 0
      };
      setState((s) => ({
        ...s,
        returns: [rec, ...s.returns],
        products: s.products.map((p) =>
          p.id !== rec.productId
            ? p
            : {
                ...p,
                variants: p.variants.map((v) => {
                  if (v.id === rec.variantId) return { ...v, stock: v.stock + rec.qty };
                  if (rec.newVariantId && v.id === rec.newVariantId) return { ...v, stock: v.stock - rec.qty };
                  return v;
                })
              }
        )
      }));
      return { ok: true };
    },
    [state.orders, state.products, state.returns]
  );

  const reset = useCallback(() => setState(buildSeed()), []);

  return { state, recordReturn, addProduct, updateProduct, deleteProduct, adjustStock, addCustomer, updateCustomer, createOrder, setOrderStatus, reset };
}

export type Role = "manager" | "staff";

export type Category = "Kurtas" | "Sarees" | "Lehengas" | "Dupattas" | "Accessories";

export const CATEGORIES: Category[] = ["Kurtas", "Sarees", "Lehengas", "Dupattas", "Accessories"];

export interface Variant {
  id: string;
  size: string;
  colour: string;
  stock: number;
}

export interface Product {
  id: string;
  name: string;
  category: Category;
  price: number;
  variants: Variant[];
}

export interface Customer {
  id: string;
  name: string;
  phone: string;
  email: string;
  city: string;
}

export type OrderStatus = "New" | "Packed" | "Delivered" | "Cancelled";

export const STATUSES: OrderStatus[] = ["New", "Packed", "Delivered", "Cancelled"];

export interface OrderLine {
  productId: string;
  variantId: string;
  name: string;
  category: Category;
  label: string;
  price: number;
  qty: number;
}

export interface Order {
  id: string;
  customerId: string;
  date: string;
  status: OrderStatus;
  lines: OrderLine[];
}

export type ReturnType = "Return" | "Exchange";
export const RETURN_TYPES: ReturnType[] = ["Return", "Exchange"];
export type ReturnReason = "Size issue" | "Damaged" | "Changed mind" | "Other";
export const RETURN_REASONS: ReturnReason[] = ["Size issue", "Damaged", "Changed mind", "Other"];

export interface ReturnRecord {
  id: string;
  type: ReturnType;
  reason: ReturnReason;
  orderId: string;
  customerId: string;
  date: string;
  productId: string;
  name: string;
  category: Category;
  variantId: string;
  label: string;
  newVariantId?: string;
  newLabel?: string;
  qty: number;
  refund: number;
}

export interface AppState {
  products: Product[];
  customers: Customer[];
  orders: Order[];
  returns: ReturnRecord[];
}

export const LOW_STOCK = 5;
